// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Editable } from "@/registry/erbium/ui/editable";

import RenameTabExample from "./variants/rename-tab";

const RenameTabSource = "import Demo from \"../examples/editable-demo\";\n\nconst Example = () => <Demo />;\n\nexport default Example;\n";

const meta = {
  component: Editable,
  parameters: {
    docs: {
      description: {
        component: "## Usage\n\nA single-line inline editor. The preview stays in the layout while the input overlays it, keeping the text position and neighboring content stable during editing. Enter or blur saves; Escape cancels.\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Button](https://base-ui.com/react/components/button)\n- [Input](https://base-ui.com/react/components/input)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Editable>;

export default { ...meta, title: "Components/Editable",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const RenameTab: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: RenameTabSource },
    },
  },
  render: RenameTabExample,
};

import { useState } from "react";
import { Editable, EditableInput, EditablePreview } from "@/registry/erbium/ui/editable";
import { Kbd } from "@/registry/erbium/ui/kbd";

const EditableDemo = () => {
  const [name, setName] = useState("Overview");

  return (
    <div className="flex w-96 items-center gap-related rounded-lg border border-transparent p-2 text-caption">
      <span className="shrink-0 text-muted-foreground">Tab</span>
      <Editable value={name} onValueChange={setName} className="min-w-0 flex-1 font-medium">
        <EditablePreview aria-label="Rename tab" />
        <EditableInput aria-label="Tab name" maxLength={48} />
      </Editable>
      <span className="inline-flex shrink-0 items-center gap-1">
        <Kbd hotkey="Enter" />
        <Kbd hotkey="Escape" />
      </span>
    </div>
  );
};

export default EditableDemo;

import Demo from "../examples/editable-demo";

const Example = () => <Demo />;

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <OverlayProvider>
      {children}
      {toast && <Toaster />}
    </OverlayProvider>
  </CSPProvider>
);

export const ShowcaseSurface = ({ children }: { children?: ReactNode }) => (
  <div
    data-slot="component-preview"
    className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
  >
    {children}
  </div>
);
